              "rationale": "Zentrale Produktziel-Anforderung ohne erkennbare Dublette auf gleichem Abstraktionsniveau.",
              "requiresHumanReview": false,
              "metadata": {}
            },
            {
              "operationId": "COP-014",
              "operation": "KEEP",
              "sourceItemIds": [
                "REQ-02"
