                  "status": "open_decision",
                  "metadata": {
                    "projectStateItemId": "REQ-10"
                  }
                }
              ],
              "rationale": "Offene Produktentscheidung, nicht durch andere Anforderungen ersetzt.",
              "requiresHumanReview": false,
